const products=[
 {id:'pro',name:'AirPods Pro 3',price:249,type:'in',image:'assets/pro-case.png',label:'PRO 3',tag:'IN-EAR · CU ADAPTOARE',desc:'Format compact. Fixare cu adaptoare din silicon.',features:['Design in-ear','Adaptoare auriculare din silicon','Culoare albă']},
 {id:'four',name:'AirPods 4',price:199,type:'in',image:'assets/four.png',label:'DE LA 199 LEI',tag:'IN-EAR · DESIGN DESCHIS',desc:'Fără adaptoare din silicon. Pentru ritmul de zi cu zi.',features:['Design deschis','Fără adaptoare din silicon','Culoare albă']},
 {id:'max',name:'AirPods Max',price:399,type:'over',image:'assets/max.png',label:'OVER-EAR',tag:'OVER-EAR · SUNETUL ÎN PRIM-PLAN',desc:'O altă perspectivă. Cupe care acoperă urechile.',features:['Format over-ear','Bandă de susținere','Imagine de prezentare; varianta se confirmă la lansare']}
];
let cart={};try{const saved=JSON.parse(localStorage.getItem('elitepods-cart')||'{}');for(const p of products){const q=Number(saved[p.id]);if(Number.isInteger(q)&&q>0&&q<=99)cart[p.id]=q;}}catch{}
let filter='all',toastTimer;const $=s=>document.querySelector(s);const money=n=>new Intl.NumberFormat('ro-RO').format(n)+' lei';
function renderProducts(){let list=products.filter(p=>filter==='all'||p.type===filter);const sort=$('#sort').value;if(sort!=='featured')list.sort((a,b)=>sort==='price-up'?a.price-b.price:b.price-a.price);$('#products').innerHTML=list.map(p=>`<article class="product-card" data-id="${p.id}"><span class="product-badge ${p.id==='pro'?'lime':''}">${p.label}</span><button class="product-image" data-detail="${p.id}" aria-label="Vezi detalii ${p.name}"><img src="${p.image}" alt="${p.name}" loading="eager" decoding="async"><span class="image-arrow" aria-hidden="true">↗</span></button><div class="product-meta"><small>${p.tag}</small><h3><a href="#${p.id}" data-detail="${p.id}">${p.name}</a></h3><p>${p.desc}</p><div class="product-bottom"><span class="price">${p.price} <small>lei</small></span><button class="add-button" data-add="${p.id}">Adaugă în coș <span>+</span></button></div></div></article>`).join('');}
function notify(msg){clearTimeout(toastTimer);$('.toast').textContent=msg;$('.toast').classList.add('show');toastTimer=setTimeout(()=>$('.toast').classList.remove('show'),2800);}
function persist(){try{localStorage.setItem('elitepods-cart',JSON.stringify(cart));}catch{}renderCart();}
function add(id){if(!products.some(p=>p.id===id))return;if((cart[id]||0)>=99){notify('Ai atins limita de 99 bucăți pentru acest model.');return;}cart[id]=(cart[id]||0)+1;persist();notify(products.find(p=>p.id===id).name+' a fost adăugat în coș.');}
function renderCart(){let count=0,total=0;const items=products.filter(p=>cart[p.id]);for(const p of items){count+=cart[p.id];total+=cart[p.id]*p.price;}document.querySelectorAll('.count').forEach(el=>el.textContent=count);$('.cart-toggle').setAttribute('aria-label',`Deschide coșul, ${count} produse`);$('#cart-content').innerHTML=items.length?items.map(p=>`<article class="cart-item"><img src="${p.image}" alt="${p.name}"><div><h3>${p.name}</h3><span class="item-price">${money(p.price)}</span><div class="quantity-line"><div class="qty"><button data-qty="${p.id}" data-delta="-1" aria-label="Scade cantitatea pentru ${p.name}">−</button><span aria-label="Cantitate">${cart[p.id]}</span><button data-qty="${p.id}" data-delta="1" aria-label="Crește cantitatea pentru ${p.name}">+</button></div><button class="remove" data-remove="${p.id}">Elimină</button></div></div></article>`).join(''):`<div class="empty-cart"><div class="empty-icon">♫</div><h3>Încă e liniște aici.</h3><p>Alege-ți perechea și dă play.</p><button class="button dark" data-browse>Descoperă colecția ↗</button></div>`;$('#cart-summary').innerHTML=items.length?`<div class="summary-line"><span>Subtotal</span><strong>${money(total)}</strong></div><div class="summary-line shipping-line"><span>Livrare (1–3 zile)</span><span>24,99 lei</span></div><div class="summary-line total-line"><span>Total cu livrare</span><strong>${money(total+24.99)}</strong></div><p class="summary-note">Transport: 24,99 lei · Livrare în 1–3 zile · Plată ramburs.</p><button class="button dark checkout" id="checkout">Continuă spre comandă <span>→</span></button><p class="summary-note" style="margin-top:12px;margin-bottom:0">Versiune de prezentare. Nu se trimit comenzi și nu se încasează plăți.</p><div id="checkout-message" role="status"></div>`:'';}
function detail(id){const p=products.find(x=>x.id===id);if(!p)return;$('#detail-content').innerHTML=`<img class="detail-photo" src="${p.image}" alt="${p.name}"><div class="detail-info"><div class="eyebrow">ELITEPODS / COLECȚIA</div><h2 id="detail-title">${p.name}</h2><p>${p.desc}</p><ul>${p.features.map(f=>`<li>${f}</li>`).join('')}</ul><span class="price">${p.price} <small>lei</small></span><button class="button dark" data-detail-add="${p.id}">Adaugă în coș <span>+</span></button><p class="summary-note" style="margin-top:14px">Comenzile vor fi disponibile la lansarea magazinului.</p></div>`;$('#detail').showModal();}
function renderSearch(){const q=$('#query').value.toLocaleLowerCase('ro').trim();const matches=products.filter(p=>p.name.toLocaleLowerCase('ro').includes(q));$('#search-results').innerHTML=matches.length?matches.map(p=>`<button class="search-result" data-search-detail="${p.id}"><img src="${p.image}" alt=""><span>${p.name}<small>${money(p.price)}</small></span>↗</button>`).join(''):'<p class="no-results">Niciun model găsit. Încearcă „Pro”, „4” sau „Max”.</p>';}
document.addEventListener('click',e=>{const addButton=e.target.closest('[data-add]');if(addButton){add(addButton.dataset.add);$('#cart').showModal();}const d=e.target.closest('[data-detail]');if(d){e.preventDefault();detail(d.dataset.detail);}if(e.target.closest('.cart-toggle')){$('#cart').showModal();}if(e.target.closest('.search-toggle')){$('#search').showModal();renderSearch();$('#query').focus();}const close=e.target.closest('.close');if(close)close.closest('dialog').close();const qty=e.target.closest('[data-qty]');if(qty){const id=qty.dataset.qty;cart[id]=Math.min(99,Math.max(0,(cart[id]||0)+Number(qty.dataset.delta)));if(!cart[id])delete cart[id];persist();}const remove=e.target.closest('[data-remove]');if(remove){delete cart[remove.dataset.remove];persist();}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{const on=b===f;b.classList.toggle('active',on);b.setAttribute('aria-pressed',on);});renderProducts();}if(e.target.closest('[data-browse]')){$('#cart').close();$('#colectie').scrollIntoView({behavior:'smooth'});}if(e.target.closest('#checkout')){startCheckout();}const da=e.target.closest('[data-detail-add]');if(da){add(da.dataset.detailAdd);$('#detail').close();$('#cart').showModal();}const sd=e.target.closest('[data-search-detail]');if(sd){$('#search').close();detail(sd.dataset.searchDetail);}});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('#sort').addEventListener('change',renderProducts);$('#query').addEventListener('input',renderSearch);$('#year').textContent=new Date().getFullYear();renderProducts();renderCart();

function startCheckout(){
 $('#cart').close();
 let subtotal=0;const chosen=products.filter(p=>cart[p.id]);
 if(!chosen.length)return;
 $('#checkout-order').innerHTML='<h3>Comanda ta</h3>'+chosen.map(p=>{subtotal+=p.price*cart[p.id];return '<div class="checkout-product"><img src="'+p.image+'" alt="'+p.name+'"><div><strong>'+p.name+'</strong><small>'+cart[p.id]+' × '+money(p.price)+'</small></div><strong>'+money(p.price*cart[p.id])+'</strong></div>';}).join('')+'<div class="summary-line"><span>Produse</span><span>'+money(subtotal)+'</span></div><div class="summary-line shipping-line"><span>Livrare · 1–3 zile</span><span>24,99 lei</span></div><div class="summary-line total-line"><strong>Total ramburs</strong><strong>'+money(subtotal+24.99)+'</strong></div><p class="summary-note">Plătești curierului la primirea coletului.</p>';
 $('#order-review').replaceChildren();$('#checkout-dialog').showModal();
}
$('#checkout-form').addEventListener('submit',e=>{
 e.preventDefault();
 if(!e.target.reportValidity())return;
 const data=new FormData(e.target);const panel=$('#order-review');
 panel.innerHTML='<div class="review-panel"><div class="eyebrow">REZUMAT DEMONSTRATIV</div><h3>Acesta este rezumatul tău.</h3><p class="review-address"></p><p>Nu a fost trimisă nicio comandă. Formularul va fi conectat la sistemul de comenzi după completarea datelor magazinului și a politicilor comerciale.</p><button class="button lime" type="button" id="review-back">Modifică datele ↑</button></div>';
 panel.querySelector('.review-address').textContent=[data.get('fullName'),data.get('phone'),data.get('address'),data.get('city'),data.get('county')].join(' · ');
 panel.scrollIntoView({behavior:'smooth',block:'end'});
});
document.addEventListener('click',e=>{if(e.target.closest('#review-back')){$('#order-review').replaceChildren();$('#checkout-form').scrollIntoView({behavior:'smooth'});}});
